tool_calls.arguments:
{"command":"kubectl patch pod app --type strategic merge --patch '
{
  "spec": {
    "containers": [
      {
        "name": "web",
        "image": "busybox:1.37.0",
        "command": [
          "sh",
          "-c",
          "httpd -f -p 8080 -h /srv"
        ],
        "imagePullPolicy": "IfNotPresent",
        "ports": [
          {
            "containerPort": 8080,
            "name": "http",
            "protocol": "TCP"
          }
        ],
        "resources": {},
        "terminationMessagePath": "/dev/termination-log",
        "terminationMessagePolicy": "File",
        "volumeMounts": [
          {
            "mountPath": "/srv",
            "name": "shared"
          },
          {
            "mountPath": "/var/run/secrets/kubernetes.io/serviceaccount",
            "name": "kube-api-access-2jcz9",
            "readOnly": true
          }
        ]
      },
      {
        "name": "page-writer",
        "image": "busybox:1.37.0",
        "command": [
          "sh",
          "-c",
          "echo <h1 > Hello Kubernetes!</h1> > /srv/index.html"
        ],
        "volumeMounts": [
          {
            "mountPath": "/srv",
            "name": "shared"
          }
        ]
      }
    ]
  }
}'"}

